<?php
$pageTitle="Ver Pedido RGPD"; $active="dashboard"; require_once "auth.php";
$id=(int)($_GET['id']??0); $stmt=$pdo->prepare("SELECT * FROM dpo_pedidos WHERE id=?"); $stmt->execute([$id]); $p=$stmt->fetch(PDO::FETCH_ASSOC); if(!$p) die("Pedido não encontrado.");
if($_SERVER['REQUEST_METHOD']==='POST'){ if(isset($_POST['estado'])){$stmt=$pdo->prepare("UPDATE dpo_pedidos SET estado=?, observacoes_admin=? WHERE id=?");$stmt->execute([$_POST['estado'],$_POST['observacoes_admin'],$id]);} if(!empty(trim($_POST['mensagem']??''))){$stmt=$pdo->prepare("INSERT INTO dpo_mensagens (pedido_id, origem, mensagem) VALUES (?, 'dpo', ?)");$stmt->execute([$id,trim($_POST['mensagem'])]);} echo "<script>window.location.href='ver.php?id=".$id."&ok=1';</script>"; exit; }
$stmt=$pdo->prepare("SELECT * FROM dpo_mensagens WHERE pedido_id=? ORDER BY criado_em ASC"); $stmt->execute([$id]); $mensagens=$stmt->fetchAll(PDO::FETCH_ASSOC);
function estadoDpo($e){return ['recebido'=>'Recebido','em_analise'=>'Em análise','respondido'=>'Respondido','arquivado'=>'Arquivado'][$e]??$e;} require_once "layout-top.php";
?><style>.grid{display:grid;grid-template-columns:1fr .8fr;gap:24px}.card{background:white;border:1px solid #e5e7eb;border-radius:24px;padding:22px;margin-bottom:20px}.line{background:#f8fafc;border:1px solid #e5e7eb;border-radius:16px;padding:13px;margin-bottom:10px}.form{display:grid;gap:12px}.form select,.form textarea{width:100%;border:1px solid #dbe4ee;background:#f8fafc;border-radius:15px;min-height:48px;padding:12px;font-weight:800}.msg{background:#f8fafc;border:1px solid #e5e7eb;border-radius:16px;padding:14px;margin-bottom:10px}@media(max-width:1000px){.grid{grid-template-columns:1fr}}</style><div class="grid"><div><div class="card"><h2><?= htmlspecialchars($p['nome']) ?></h2><span class="badge"><?= htmlspecialchars($p['codigo']) ?></span><span class="badge"><?= htmlspecialchars(estadoDpo($p['estado'])) ?></span></div><div class="card"><h2>Dados do pedido</h2><div class="line"><strong>Email:</strong> <?= htmlspecialchars($p['email']) ?></div><div class="line"><strong>Data:</strong> <?= date('d/m/Y H:i', strtotime($p['criado_em'])) ?></div><div class="line"><strong>Mensagem:</strong><br><?= nl2br(htmlspecialchars($p['mensagem'])) ?></div></div></div><div><div class="card"><h2>Gestão</h2><form method="POST" class="form"><label>Estado</label><select name="estado"><?php foreach(['recebido','em_analise','respondido','arquivado'] as $e): ?><option value="<?= $e ?>" <?= $p['estado']===$e?'selected':'' ?>><?= estadoDpo($e) ?></option><?php endforeach; ?></select><label>Observações internas</label><textarea name="observacoes_admin"><?= htmlspecialchars($p['observacoes_admin']??'') ?></textarea><label>Mensagem para acompanhamento</label><textarea name="mensagem"></textarea><button class="btn">Guardar</button></form></div><div class="card"><h2>Mensagens</h2><?php foreach($mensagens as $m): ?><div class="msg"><strong><?= $m['origem']==='dpo'?'DPO':'Cidadão' ?></strong><br><?= nl2br(htmlspecialchars($m['mensagem'])) ?><br><small><?= date('d/m/Y H:i', strtotime($m['criado_em'])) ?></small></div><?php endforeach; ?><?php if(empty($mensagens)): ?><p>Sem mensagens.</p><?php endif; ?></div></div></div><?php require_once "layout-bottom.php"; ?>